/*
 * THE COACH'S PEOPLE (TASK-L170 §1), from rows. Ported from
 * src/lib/server/coach/roster-service.ts `rosterQuery` and its three laterals.
 *
 * STARTS FROM ACCOUNTS, NOT FROM PROJECTS (L89): a learner who signed up and
 * stopped halfway through onboarding still has a row, because that is exactly
 * the person a coach most needs to notice. Every derived field is nullable;
 * `cohorts` and `programmes` are `[]`, never null.
 *
 * NO JOINS (§3). The product's roster is ONE statement; here it is one query per
 * collection, all in parallel, reassembled below — L89's "one statement" does
 * not survive the port and this says so. Each read is unfiltered because the
 * roster is everyone, and is bounded by the backend's 1,000-row page (PRD-001):
 * past that a coach's roster would be silently short, which is stated rather
 * than hidden.
 *
 * The gate is `role:staff` in nodegx.security.json. `coachLabel` is the
 * trainer's private shorthand (L84) and this is the only function that serves it.
 */
(async () => {
  try {
    /* A Records row is a Noodl Model: its fields serialise and its id does NOT —
       the id is `getId()`. The first version keyed accounts on `objectId`, found
       nothing live, and served every email and every account date as null. */
    const plain = (m) => JSON.parse(JSON.stringify({
      ...(m && typeof m.toJSON === 'function' ? m.toJSON() : m),
      objectId: m && typeof m.getId === 'function' ? m.getId() : m && m.objectId
    }));
    const q = async (c) => (await Noodl.Records.query(c, {}, { limit: 1000 })).map(plain);
    const [users, profiles, contexts, invites, paths, steps, progress, artifacts, members, cohorts,
      conversations, messages, programmes] = await Promise.all([
      q('_User'), q('LearnerProfile'), q('ProjectContext'), q('LearnerInvite'), q('LearningPath'), q('PathStep'),
      q('Progress'), q('ArtifactSubmission'), q('CohortMember'), q('Cohort'), q('Conversation'),
      q('ConversationMessage'), q('Programme')
    ]);
    const nul = (v) => (v === undefined ? null : v);
    const iso = (v) => (v === undefined || v === null ? null : new Date(v).toISOString());
    const newest = (list) => list.reduce((best, x) => (best === null || x > best ? x : best), null);
    const userById = new Map(users.map((u) => [u.objectId, u]));
    const cohortById = new Map(cohorts.map((c) => [c.cohortId, c]));

    const people = profiles.map((lp) => {
      const id = lp.learnerId;
      // A profile holds its account's OBJECT ID, not a username (lib/seed-resolve.mjs).
      const account = userById.get(lp.userId) || {};
      const context = contexts.find((c) => c.learnerId === id) || null;
      // The trainer's label, from the invite this person was claimed from.
      const invite = invites
        .filter((i) => i.claimedByLearnerId === id)
        .sort((a, b) => (iso(b.claimedAt) || '').localeCompare(iso(a.claimedAt) || ''))[0];
      // The ACTIVE path is the most recent one; a replan writes a new row (L86).
      const path = paths.filter((p) => p.learnerId === id).sort((a, b) => (iso(a.createdAt) < iso(b.createdAt) ? 1 : -1))[0];
      // Removed steps are counted nowhere (L113).
      const live = path ? steps.filter((s) => s.pathId === path.pathId && nul(s.removedAt) === null) : [];
      // GREATEST skips NULLs and is NULL only when every input is — so "no
      // activity yet" is null, never the word "never" (L89).
      const lastActivity = newest(
        [context ? iso(context.updatedAt) : null,
          newest(progress.filter((p) => p.learnerId === id).map((p) => iso(p.updatedAt))),
          newest(artifacts.filter((a) => a.learnerId === id).map((a) => iso(a.submittedAt)))].filter((x) => x !== null)
      );
      // A DATE, never a count: the earliest learner turn nobody has opened (L119).
      const threads = new Set(conversations.filter((c) => c.learnerId === id).map((c) => c.conversationId));
      const waiting = messages
        .filter((m) => threads.has(m.conversationId) && m.authorRole === 'learner' && nul(m.readAt) === null)
        .map((m) => iso(m.createdAt))
        .sort();
      return {
        learnerId: id,
        email: nul(account.email),
        coachLabel: invite ? nul(invite.label) : null,
        projectName: context ? nul(context.projectName) : null,
        contextVersion: context ? nul(context.version) : null,
        stepsTotal: live.length,
        stepsComplete: live.filter((s) => s.status === 'complete').length,
        lastActivity,
        createdAt: iso(account.createdAt),
        coachEmail: nul(lp.coachEmail),
        replanBlockedAt: path ? iso(path.replanBlockedAt) : null,
        awaitingReplySince: waiting.length ? waiting[0] : null,
        // Trainer-assigned groups only: the lounge is on every row and is
        // therefore not information (L104). Ordered by name.
        cohorts: members
          .filter((m) => m.learnerId === id && nul(m.removedAt) === null)
          .map((m) => cohortById.get(m.cohortId))
          .filter((c) => c && !c.isDefault)
          .map((c) => ({ id: c.cohortId, name: c.name }))
          .sort((a, b) => a.name.localeCompare(b.name)),
        // A LIST, never a LIMIT 1 (sprint 35 §5.2). Archived and closed ones are
        // included; the roster's own filter is the page's business (L124).
        programmes: programmes
          .filter((p) => p.learnerId === id)
          .map((p) => ({ id: p.programmeId, title: p.title, startsOn: nul(p.startsOn), endsOn: nul(p.endsOn),
            status: p.status, archivedAt: iso(p.archivedAt), createdAt: iso(p.createdAt) }))
          .sort((a, b) => {
            if (a.endsOn !== b.endsOn) {
              if (a.endsOn === null) return 1;
              if (b.endsOn === null) return -1;
              return a.endsOn < b.endsOn ? -1 : 1;
            }
            return (b.createdAt || '').localeCompare(a.createdAt || '');
          })
      };
    });
    // The product's ORDER BY: lastActivity DESC NULLS LAST, then createdAt DESC.
    people.sort((a, b) => {
      if (a.lastActivity === null && b.lastActivity !== null) return 1;
      if (b.lastActivity === null && a.lastActivity !== null) return -1;
      if (a.lastActivity !== b.lastActivity) return a.lastActivity < b.lastActivity ? 1 : -1;
      if (a.createdAt !== b.createdAt) return (b.createdAt || '').localeCompare(a.createdAt || '');
      // The product leaves a full tie to the database; here it is total, by id.
      return a.learnerId.localeCompare(b.learnerId);
    });
    Outputs.rows = people;
    Outputs.done();
  } catch (e) {
    Outputs.error = String((e && e.message) || e);
    // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
    console.error('[dbt:roster]', Outputs.error);
    Outputs.failed();
  }
})();
